%[text] # Simulation case
model_name = "HarnessModel_ElevationProfile";
load_system(model_name)
sim_in = Simulink.SimulationInput(model_name);
%[text] Road Grade Profile block
loadParameters_ElevationProfile
%[text] Brake Force Input block
block_path = model_name + "/Braking Force Input";

sim_in = setBlockParameter(sim_in, block_path, x = "[0, 1, 2, 3, 4, 5]");
sim_in = setBlockParameter(sim_in, block_path, x_unit = "s");

sim_in = setBlockParameter(sim_in, block_path, f = "[8 8 8 0 0 0]");
sim_in = setBlockParameter(sim_in, block_path, f_unit = "kN");
%[text] Torque Command Input block
block_path = model_name + "/Torque Command Input";

LUT_MotorTorqueCommand = table( ...
  simscape.Value([0 1 3,  4 5 140,  150 160 180,  190 200 210,  220 230 240], "s"), ...
  simscape.Value([0 0 0,  20 20 20,  30 30 30,  10 10 10,  0 0 0], "N*m"), ...
  VariableNames = ["Time", "MotorTorqueCommand"] );

sim_in = setBlockParameter(sim_in, block_path, x = "[0 1 3,  4 5 140,  150 160 180,  190 200 210,  220 230 240]");
sim_in = setBlockParameter(sim_in, block_path, x_unit = "s");

sim_in = setBlockParameter(sim_in, block_path, f = "[0 0 0,  20 20 20,  30 30 30,  10 10 10,  0 0 0]");
sim_in = setBlockParameter(sim_in, block_path, f_unit = "N*m");
%[text] 
sim_in = setModelParameter(sim_in, StopTime = "300");
applyToModel(sim_in)
%%
%[text] Run simulation
sim_out = sim(sim_in);
result = bevutil1.SignalUtil.getTimetableFromLoggedSignal(sim_out.logsout);
%%
varnames = [
"Braking force"
"Torque command"
"Elevation"
"Road grade"
"Vehicle speed"
"Vehicle force"
"G force"
"Battery charge"
"Battery current"
"Battery voltage"
"Motor current"
"Motor torque"
"Motor angular speed"
"Motor voltage"
];

function vec = get_simscapeValue_vector(tt, name)
logical_index = tt.Properties.VariableNames == name;
unit_text = string(tt.Properties.VariableUnits(logical_index));
vec = simscape.Value(tt.(name), unit_text);
end  % local function
%[text] Powers in each component
V_vehicle = get_simscapeValue_vector(result, "Vehicle speed");
F_vehicle = get_simscapeValue_vector(result, "Vehicle force");
P_vehicle = convert(V_vehicle .* F_vehicle, "kW");
VehiclePowerTable = timetable(result.Time, P_vehicle, VariableNames="Vehicle power");

w_motor = get_simscapeValue_vector(result, "Motor angular speed");
trq_motor = get_simscapeValue_vector(result, "Motor torque");
P_motor = convert(w_motor .* trq_motor, "kW");
MotorPowerTable = timetable(result.Time, P_motor, VariableNames="Motor power");

i_battery = get_simscapeValue_vector(result, "Battery current");
v_battery = get_simscapeValue_vector(result, "Battery voltage");
P_battery = convert(i_battery .* v_battery, "kW");
BatteryPowerTable = timetable(result.Time, P_battery, VariableNames="Battery power");

bevutil1.SignalUtil.plotTimedData(TimedData=VehiclePowerTable, SignalName="Vehicle power", FigureHeight=200); %[output:1c981438]
bevutil1.SignalUtil.plotTimedData(TimedData=MotorPowerTable, SignalName="Motor power", FigureHeight=200); %[output:216092e1]
bevutil1.SignalUtil.plotTimedData(TimedData=BatteryPowerTable, SignalName="Battery power", FigureHeight=200); %[output:2613c679]
%%
%[text] Plot logged signals
for k = 1 : numel(varnames) %[output:group:24d070e5]
  bevutil1.SignalUtil.plotTimedData(TimedData=result, SignalName=varnames(k), FigureHeight=200); %[output:8887f177] %[output:703f2939] %[output:4296ebe4] %[output:4a7d8806] %[output:76a2194a] %[output:4fbb6541] %[output:7a8b5e6a] %[output:99ca0a58] %[output:497095a9] %[output:28b8a732] %[output:026ed003] %[output:02ed2a40] %[output:4f851af6] %[output:3cac0d15]
end  % for %[output:group:24d070e5]
